const button=document.getElementById("theme-switcher-button");const popup=document.getElementById("theme-switcher-popup");const savedTheme=localStorage.getItem("theme");if(savedTheme){const savedCssClass=popup.querySelector(`button[data-theme="${savedTheme}"]`).getAttribute("data-css-class");document.body.setAttribute("data-theme",savedTheme);document.body.classList.add(savedCssClass);}else{const defaultTheme=popup.dataset.defaultTheme;const defaultButton=popup.querySelector(`button[data-theme="${defaultTheme}"]`);console.log("defaultButton",defaultButton);const defaultCssClass=defaultButton.getAttribute("data-css-class");document.body.setAttribute("data-theme",defaultTheme);document.body.classList.add(defaultCssClass);}button.addEventListener("click",()=>{popup.style.display=popup.style.display==="none"?"":"none";});popup.querySelectorAll("button").forEach(btn=>{btn.addEventListener("click",()=>{let oldTheme=document.body.getAttribute("data-theme");if(oldTheme){let oldCssClass=popup.querySelector(`button[data-theme="${oldTheme}"]`).getAttribute("data-css-class");document.body.classList.remove(oldCssClass);document.body.removeAttribute("data-theme");localStorage.removeItem("theme");}document.body.setAttribute("data-theme",btn.getAttribute("data-theme"));document.body.classList.add(btn.getAttribute("data-css-class"));localStorage.setItem("theme",btn.getAttribute("data-theme"));popup.style.display="none";});});